Rewrite the following GNU C++17 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to rewrite:
<original_code>
#include<bits/stdc++.h>
using namespace std;
const int N=510;
typedef pair<int,int> pii;
#define mp make_pair
#define fi first
#define se second

int n,m,mod,C[N][N];
pii dp[N][N];

int add(int a,int b) {
	return a+b>=mod?a+b-mod:a+b;
}

pii operator+(const pii &a,const pii &b) {
	return mp(add(a.fi,b.fi),add(a.se,b.se));
}

pii operator*(const pii &a,const pii &b) {
	return mp(1ll*a.fi*b.fi%mod,(1ll*a.fi*b.se+1ll*a.se*b.fi)%mod);
}

int s1(int l,int r) {
	return (l+r)*(r-l+1)/2;
}

int main() {
#ifdef LOCAL
	freopen("a.in","r",stdin);
	freopen("a.out","w",stdout);
#endif
	ios::sync_with_stdio(0);cin.tie(0);
	cin>>n>>m>>mod;
	for(int i=0;i<N;i++) {
		C[i][0]=1;
		for(int j=1;j<=i;j++) C[i][j]=add(C[i-1][j],C[i-1][j-1]);
	}
	for(int i=0;i<=n;i++) {
		dp[i][0]=mp(1,0);
		for(int j=1;j<=i&&j<=m;j++) {
			if(i!=j) {
				for(int k=1;k<=i;k++)
					dp[i][j]=dp[i][j]+dp[k-1][k-1]*dp[i-k][j-k+1]*mp(C[j][k-1],0);
			}
			else {
				for(int k=1;k<=i;k++) {
					dp[i][j]=dp[i][j]+dp[k-1][k-1]*dp[i-k][i-k]*mp(C[i-1][k-1],0)*mp(i+1,k*k-s1(1,k)+s1(k+1,i)-k*(i-k));
					//if(i==2&&j==2) cerr<<dp[i][j].fi<<' '<<dp[i][j].se<<'\n';
				}
			}
			//cerr<<i<<' '<<j<<' '<<dp[i][j].fi<<' '<<dp[i][j].se<<'\n';
		}
	}
	cout<<dp[n][m].se;
	return 0;
}

